基础快排:选 pivot(末位/随机/三数取中),partition 使左小右大,递归两边。复杂度:平均 O(nlogn),最坏 O(n²)(已排序+末位 pivot)。三路快排(<pivot/=pivot/>pivot 三段)针对重复元素避免退化:扫描时 lt 维护小于区间尾,i 当前,gt 大于区间头;nums[i]<pivot 交换 nums[lt+1] 与 nums[i] lt++ i++;=pivot i++;>pivot 交换 nums[gt-1] 与 nums[i] gt-- 不增 i。代码:
```
function quickSort(nums, l, r) {
  if (l >= r) return;
  const pivot = nums[l + Math.floor(Math.random() * (r - l + 1))];
  let lt = l - 1, i = l, gt = r + 1;
  while (i < gt) {
    if (nums[i] < pivot) { [nums[++lt], nums[i++]] = [nums[i], nums[lt]]; }
    else if (nums[i] > pivot) { [nums[--gt], nums[i]] = [nums[i], nums[gt]]; }
    else i++;
  }
  quickSort(nums, l, lt); quickSort(nums, gt, r);
}
```
优化:随机 pivot 防最坏、三路去重、小数组切插入排序、尾递归优化。

解法 1:排序后取末 K,O(nlogn) 简单但非最优。解法 2:小顶堆 size=K,遍历维护堆,O(nlogK) 适合流式数据。代码:
```
function topK(nums, k) {
  const heap = new MinPriorityQueue();
  for (const n of nums) {
    heap.enqueue(n);
    if (heap.size() > k) heap.dequeue();
  }
  return heap.toArray().map(x => x.element);
}
```
解法 3:QuickSelect 快速选择,基于 partition 平均 O(n),最坏 O(n²),随机 pivot 优化。代码:
```
function findKthLargest(nums, k) {
  const target = nums.length - k;
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const p = partition(nums, l, r);
    if (p === target) return nums[p];
    else if (p < target) l = p + 1;
    else r = p - 1;
  }
  return nums[l];
}
```
解法 4:计数排序 O(n) 适合值域小(如年龄)。选型:大数据流用堆,内存够且要平均快用 QuickSelect,值域小用计数。

Trie 节点:children Map + isEnd + (扩展)frequency + word。insert:逐字符走/建子节点,末节点 isEnd=true,frequency++。search:走完字符且 isEnd=true。startsWith:走完字符即可。自动补全:startsWith 定位前缀节点,BFS/DFS 收集所有 word,按 frequency 排序取 TopK。优化:1) TopK 用堆;2) 节点预存 TopK word 列表(空间换时间);3) 压缩 Trie(Radix Tree)合并单链。代码:
```
class TrieNode {
  children = new Map(); isEnd = false; freq = 0; word = '';
}
class Trie {
  root = new TrieNode();
  insert(word) {
    let node = this.root;
    for (const c of word) {
      if (!node.children.has(c)) node.children.set(c, new TrieNode());
      node = node.children.get(c);
    }
    node.isEnd = true; node.freq++; node.word = word;
  }
  search(word) { /* walk & check isEnd */ }
  startsWith(prefix) { /* walk & return node */ }
  suggest(prefix, k) {
    const node = this.startsWith(prefix);
    if (!node) return [];
    const res = [];
    const dfs = (n) => {
      if (n.isEnd) res.push({ word: n.word, freq: n.freq });
      for (const child of n.children.values()) dfs(child);
    };
    dfs(node);
    return res.sort((a,b) => b.freq - a.freq).slice(0, k).map(x => x.word);
  }
}
```
